function advance(){if(mode==='journey'&&phase<2){phase++;render();return}stars++;sessionDone++;save();updateStats();pos++;phase=0;render()}
function finish(){$('#game').dataset.active='false';let world=currentWorld();$('#game').innerHTML='<div class="missionMascot">'+world.reward+'</div><div class="eyebrow">MISSIONE COMPLETATA</div><h2>'+esc(world.success)+'</h2><p>'+sessionDone+' parole allenate · '+sessionDone+' stelle per il tuo impegno</p><div class="reward">'+Array.from({length:Math.min(sessionDone,10)},()=> '⭐').join(' ')+'</div><p>'+(mistakes.length?'Ci sono '+mistakes.length+' parole da allenare ancora. Le trovi nel ripasso.':'Ottimo lavoro! Ora puoi fare una pausa o scegliere un altro mondo.')+'</p><button class="primary" id="again">Un’altra missione</button><button class="audio" id="rest">Scegli l’avventura</button>';$('#again').onclick=start;$('#rest').onclick=home;if(mistakes.length){let b=document.createElement('button');b.className='audio';b.textContent='🎯 Ripassa queste parole';b.onclick=()=>{queue=allWords().filter(x=>mistakes.includes(x[0]));pos=0;phase=0;mistakes=[];sessionDone=0;render()};$('#game').appendChild(b)}}
