$('#category').innerHTML=Object.entries(names).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});home()});$('#category').onchange=home;$('#start').onclick=start;$('#voice').onchange=()=>{voiceName=$('#voice').value;save()};$('#customWords').value=custom.map(x=>x[0]+' = '+x[1]).join('\n');$('#save').onclick=()=>{let rows=$('#customWords').value.split('\n').filter(x=>x.trim()),parsed=rows.map(x=>x.split('=').map(y=>y.trim()));if(parsed.some(x=>x.length!==2||!(/^[a-z][a-z '’?,.!-]{0,79}$/i.test(x[0]))||!x[1])){$('#saved').textContent='Usa inglese = italiano, una voce per riga (massimo 80 caratteri).';return}custom=parsed.map(x=>[x[0],x[1],'✨']);save();$('#saved').textContent='Salvato!';$('#category').value='custom';home()};updateStats();loadVoices();if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=loadVoices;initWorlds();home();
